#!/bin/bash
# Type checks the mod with the Lua language server against the Factorio API, the same diagnostics VS Code shows.
# Uses the language server from the sumneko.lua VS Code extension and the Factorio API types generated by the
# Factorio Mod Debug extension (justarandomgeek.factoriomod-debug), both found automatically.
#
# Usage: tools/check.sh [path...]   (defaults to the whole mod)
#   LUA_LS=/path/to/lua-language-server   override the language server
#   FACTORIO_TYPES=/path/to/sumneko-3rd/factorio   override the API types

set -u

MOD_DIR="$(cd "$(dirname "$0")/.." && pwd)"

newest() { ls -td "$@" 2> /dev/null | head -n 1; }

LUA_LS="${LUA_LS:-$(newest "$HOME"/.vscode/extensions/sumneko.lua-*/server/bin/lua-language-server)}"
FACTORIO_TYPES="${FACTORIO_TYPES:-$(newest "$HOME/Library/Application Support/Code/User/workspaceStorage"/*/justarandomgeek.factoriomod-debug/sumneko-3rd/factorio)}"

if [ ! -x "$LUA_LS" ]; then
  echo "lua-language-server not found, install the sumneko.lua VS Code extension or set LUA_LS"
  exit 2
fi
if [ ! -d "$FACTORIO_TYPES" ]; then
  echo "Factorio API types not found: open the mod in VS Code with the Factorio Mod Debug extension once, or set FACTORIO_TYPES"
  exit 2
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# Factorio's runtime (from the types' config.json) plus the repo's own .luarc.json settings
python3 - "$FACTORIO_TYPES" "$MOD_DIR/.luarc.json" "$WORK/luarc.json" <<'EOF'
import json, sys
types, repo_config, out = sys.argv[1:]
config = {
    "runtime.version": "Lua 5.2",
    "runtime.path": ["?.lua"],
    "runtime.builtin": {"io": "disable", "os": "disable", "coroutine": "disable"},
    "runtime.plugin": types + "/plugin.lua",
    "workspace.library": [types + "/library"],
    "workspace.checkThirdParty": False,
    "diagnostics.globals": ["__DebugAdapter", "__Profiler"],
    "diagnostics.disable": ["lowercase-global"],
}
with open(repo_config) as f:
    for key, value in json.load(f).items():
        if isinstance(value, dict) and isinstance(config.get(key), dict):
            config[key].update(value)
        else:
            config[key] = value
with open(out, "w") as f:
    json.dump(config, f)
EOF

cd "$MOD_DIR" || exit 2
"$LUA_LS" --check . --configpath="$WORK/luarc.json" --checklevel=Warning \
  --logpath="$WORK/log" --check_out_path="$WORK/out.json" > "$WORK/stdout.txt" 2>&1

if [ ! -f "$WORK/out.json" ]; then
  # no problems: the language server doesn't write the file at all
  grep -q "no problems found" "$WORK/stdout.txt" && echo "No problems" && exit 0
  cat "$WORK/stdout.txt"
  exit 2
fi

python3 - "$WORK/out.json" "$MOD_DIR" "$@" <<'EOF'
import json, sys, urllib.parse
out, mod_dir, *only = sys.argv[1:]
problems = []
results = json.load(open(out))
# an empty list when nothing was found
for uri, diagnostics in (results.items() if isinstance(results, dict) else []):
    path = urllib.parse.unquote(uri.removeprefix("file://"))
    path = path.removeprefix(mod_dir + "/")
    if only and not any(path.startswith(prefix.rstrip("/")) for prefix in only):
        continue
    for d in diagnostics:
        line = d["range"]["start"]["line"] + 1
        column = d["range"]["start"]["character"] + 1
        problems.append((path, line, column, f"{path}:{line}:{column}: {d['message'].splitlines()[0][:200]} [{d['code']}]"))
for *_, problem in sorted(problems):
    print(problem)
print(f"{len(problems)} problems" if problems else "No problems")
sys.exit(1 if problems else 0)
EOF
